import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  texture,
  dot,
  sin,
  fract,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DoubleSide, DirectionalLight, Texture } = THREE;

  const colors = config.colors ??
    config.intent?.visualSpec?.colors ?? {
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      surface: '#0b0b10',
    };

  const group = new Group();
  group.name = 'pricing-card-2';

  // apply rotation / scale from config (position is handled by the adapter)
  const rot = config.rotation ?? config.scenePosition?.rotation;
  if (rot) group.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  const scl = config.scale ?? config.scenePosition?.scale;
  if (scl) group.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  const inner = new Group();
  group.add(inner);

  // --- geometry / material -------------------------------------------------
  const width = 2.4;
  const height = 1.5;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  // placeholder texture swapped when the real one resolves
  const placeholderTex = new Texture();
  const mapNode = texture(placeholderTex, uv());

  const topColor = color(colors.ink);
  const bottomColor = color(colors.surface);
  const paperColor = color(colors.paper);
  const accentColor = color(colors.accent);

  const gradient = mix(bottomColor, topColor, uv().y);

  // subtle top lip highlight (paper, kept dim so it never becomes the brightest element)
  const lip = smoothstep(0.94, 1.0, uv().y).mul(0.3);
  const lipTint = paperColor.mul(lip);

  // thin accent strip along the bottom edge, kept well under 10% of the card area
  const band = smoothstep(0.0, 0.018, uv().y).oneMinus();
  const accentTint = accentColor.mul(band).mul(0.7);

  // cheap procedural grain
  const grain = fract(sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453));
  const grainFactor = float(1.0).sub(grain.mul(0.04));

  // brushed-metal texture modulation (kept subtle so palette stays exact)
  const texColor = mapNode.rgb;
  const texLum = texColor.r.add(texColor.g).add(texColor.b).div(3.0);
  const metalMod = mix(float(1.0), texLum, 0.22);

  const finalColor = gradient
    .mul(metalMod)
    .mul(grainFactor)
    .add(lipTint)
    .add(accentTint);

  const material = new MeshPhysicalNodeMaterial({
    side: DoubleSide,
  });
  material.colorNode = finalColor;
  material.roughness = 0.56;
  material.metalness = 0.5;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.35;

  const mesh = new Mesh(geometry, material);
  mesh.name = 'pricing-card-2-surface';
  inner.add(mesh);

  // load the brushed metal map, wire it into the existing node graph
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      mapNode.value = tex;
      material.needsUpdate = true;
    });
  }

  // --- node-local lighting (rim carries the accent hue, stays under caps) --
  const rimLight = new DirectionalLight(colors.accent, 0.75);
  rimLight.position.set(-1.4, 1.1, -1.8);
  inner.add(rimLight);

  // --- text content (bridged, currently none for this element) -----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  for (const item of items) {
    if (!item?.text) continue;
    const t = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 24,
      color: colors.paper,
      align: 'left',
    });
    inner.add(t);
    textNodes.push(t);
  }

  // --- primitives (none specified for this node, loop kept for parity) ----
  const primitiveCleanups = [];
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const result = fn(group, prim.params ?? {});
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  // --- weighted-settle entrance (no linear easing, weight-appropriate) ----
  inner.scale.setScalar(0.96);
  const timeline = gsap.timeline();
  timeline.to(inner.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });

  // --- event handler surface (no interactions defined for this element) ---
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timeline.kill();
    for (const fn of primitiveCleanups) {
      try {
        fn();
      } catch (e) {
        /* no-op */
      }
    }
    for (const t of textNodes) {
      t.parent?.remove(t);
      t.traverse?.((child) => {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      });
    }
    geometry.dispose();
    material.dispose();
    if (mapNode.value && mapNode.value.dispose) {
      mapNode.value.dispose();
    }
    placeholderTex.dispose();
    rimLight.dispose?.();
    inner.remove(rimLight);
    inner.remove(mesh);
    group.remove(inner);
  };

  return group;
}
